import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

const clampInt = (min, max, fallback) =>
  z.coerce.number().int().transform((value) => _.clamp(value, min, max)).default(fallback);

const text = (fallback = '') => z.string().default(fallback);

const BondSchema = z.object({
  user羁绊等级: clampInt(0, 10, 0),
  user好感度: clampInt(0, 100, 0),
  御主羁绊等级: clampInt(0, 10, 10),
}).default({});

const CharacterSchema = z.object({
  名字: text('未知从者'),
  是否在场: z.coerce.boolean().default(true),
  当前位置: text('未知'),
  羁绊: BondSchema,
  当前心里话: text('无'),
  契约状态: z.enum(['无', '补魔契约', '专属补魔契约']).default('无'),
  性兴奋度: clampInt(0, 100, 0),
  受精状态: z.object({
    是否可受精: z.coerce.boolean().default(false),
    是否已受精: z.coerce.boolean().default(false),
    受精对象: text('无'),
    受精时间: text('无'),
    受精地点: text('无'),
  }).default({}),
  妊娠状态: z.object({
    是否妊娠: z.coerce.boolean().default(false),
    妊娠阶段: z.enum(['无', '早期', '中期', '后期', '稳定妊娠']).default('无'),
    腹部状态: text('平坦'),
    圣杯实体化: z.coerce.boolean().default(false),
    避孕术式: z.enum(['启用', '解除', '无']).default('启用'),
    妊娠性质: text('无生命创造，仅作为角色身体状态记录'),
  }).default({}),
  追加补魔: z.object({
    持有精液避孕套数量: z.coerce.number().int().transform((value) => Math.max(0, value)).default(0),
    避孕套存放位置: text('无'),
  }).default({}),
  穿搭: z.record(z.string(), z.string()).default({
    上装: '迦勒底制服上衣',
    下装: '迦勒底制服裙',
    内衣: '普通款式内衣',
    裤袜: '黑色连裤袜',
    鞋子: '制服皮鞋',
  }),
  生理状态: z.object({
    小穴: text('正常'),
    胸部: text('正常'),
    肛门: text('正常'),
  }).default({}),
  最近性行为: z.object({
    对象: text('无'),
    场景: text('无'),
  }).default({}),
}).passthrough().default({});

export const Schema = z.object({
  世界状态: z.object({
    当前日期: text('2026年01月01日'),
    当前时间: text('08点00分'),
    当前地点: text('迦勒底走廊'),
    当前交互从者: text('玛修・基列莱特'),
  }).default({}),
  羁绊系统: z.record(z.string(), BondSchema).default({}),
  角色状态: z.record(z.string(), CharacterSchema).default({}),
  MVUStatMenu_DB_Ver: text('fgo-chaldea-mvu-2.0.0'),
  GameStarted: z.coerce.boolean().default(false),
}).superRefine((data, ctx) => {
  for (const [name, character] of Object.entries(data.角色状态 ?? {})) {
    const bond = data.羁绊系统?.[name] ?? data.羁绊系统?.[character.名字] ?? character.羁绊;
    if (!bond) continue;

    const affectionCap = bond.user羁绊等级 <= 5 ? 50 : 100;
    if (bond.user好感度 > affectionCap) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['羁绊系统', name, 'user好感度'],
        message: `user好感度 exceeds cap ${affectionCap}.`,
      });
    }

    if (bond.user羁绊等级 <= 5 && bond.御主羁绊等级 !== 10) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['羁绊系统', name, '御主羁绊等级'],
        message: '御主羁绊等级 must stay at 10 while user羁绊等级 is 0-5.',
      });
    }

    if (bond.user羁绊等级 === 10 && bond.御主羁绊等级 !== 0) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['羁绊系统', name, '御主羁绊等级'],
        message: '御主羁绊等级 must be 0 when user羁绊等级 reaches 10.',
      });
    }

    if (character.契约状态 === '补魔契约' && bond.user羁绊等级 < 6) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['角色状态', name, '契约状态'],
        message: '补魔契约 requires user羁绊等级 >= 6.',
      });
    }

    if (character.契约状态 === '专属补魔契约' && (bond.user羁绊等级 < 8 || bond.御主羁绊等级 >= 6)) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['角色状态', name, '契约状态'],
        message: '专属补魔契约 requires user羁绊等级 >= 8 and 御主羁绊等级 < 6.',
      });
    }

    const fertilizationSource = String(character.受精状态?.受精对象 ?? '');
    if (/藤丸立香|御主|Fujimaru\s*Ritsuka/i.test(fertilizationSource)) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['角色状态', name, '受精状态', '受精对象'],
        message: '藤丸立香（男）/御主 cannot be recorded as 受精对象.',
      });
    }

    if (character.妊娠状态?.是否妊娠 && !character.受精状态?.是否已受精) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['角色状态', name, '妊娠状态', '是否妊娠'],
        message: '妊娠状态 requires 受精状态.是否已受精 to be true.',
      });
    }

    if (character.妊娠状态?.是否妊娠 && bond.user羁绊等级 !== 10) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['角色状态', name, '妊娠状态', '是否妊娠'],
        message: '妊娠状态 requires user羁绊等级 to be exactly 10.',
      });
    }

    if (character.受精状态?.是否可受精 && !character.妊娠状态?.圣杯实体化 && character.妊娠状态?.避孕术式 !== '解除') {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['角色状态', name, '受精状态', '是否可受精'],
        message: '是否可受精 requires 圣杯实体化 or 避孕术式=解除.',
      });
    }
  }
}).default({});

$(() => {
  registerMvuSchema(Schema);
});
